        await $c.win.alert('이 값을 부모 화면으로 보내는 방식을 아직 정하지 못했습니다(전환 미완) — 배열 파라미터 표현');

        if (index == 2) {
            scwin.call_magnt_tp_cd.setValue('');
            $c.util.getComponent("ipt_callExerRsn").setValue('');
            $c.util.getComponent("cal_fstCallExerDd").setValue('');
            $c.util.getComponent("ipt_callMmendTpCd").setValue('');
            $c.util.getComponent("ipt_callExerCycle").setValue('');
            $c.util.getComponent("ipt_callExerCnt").setValue('');
            $("#tbl_call tr").remove();
            parentfm.call_count.value = '0';
        }
        parentfm.put_save_yn.value = "Y";
    }
    if (parentfm.imbdopt_corpbnd_cd[3].checked) {
        parentfm.imbdopt_corpbnd_cd[3].checked = false;
    }
    parent.$c.win.closePopup();
    /* sdd-asis-lifecycle:end */
};


