/**
 * @method
 * @name scwin.calc_data_Chk
 * @author Inswave
 * @date 2026. 09. 29
 * @param id
 * @returns
 * @hidden N
*/
scwin.calc_data_Chk = async function (id) {
    /* sdd-asis-lifecycle:begin calc_data_Chk — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fm = (document.InputForm || { elements: [] });
    if (id === "Call") {
        if ($c.str.getByteLength($c.util.getComponent('cal_fstCallExerDd').getValue()) == 0) {
            await $c.win.alert("'최초 콜옵션 행사일'을 입력하십시오.");
            $c.util.getComponent("cal_fstCallExerDd").focus();
            return false;
        }
        if ($c.str.getByteLength($c.util.getComponent('ipt_callExerCycle').getValue()) == 0) {
            await $c.win.alert("'콜옵션 행사주기'를 입력하십시오.");
            $c.util.getComponent("ipt_callExerCycle").focus();
            return false;
        }
        if ($c.str.getByteLength($c.util.getComponent('ipt_callExerCnt').getValue()) == 0) {
            await $c.win.alert("'콜옵션 행사횟수'를 입력하십시오.");
            $c.util.getComponent("ipt_callExerCnt").focus();
            return false;
        }
    } else {
        if (id === "Put") {
            if ($c.str.getByteLength($c.util.getComponent('cal_fstPutExerDd').getValue()) == 0) {
                await $c.win.alert("'최초 풋옵션 행사일'을 입력하십시오.");
                $c.util.getComponent("cal_fstPutExerDd").focus();
                return false;
            }
            if ($c.str.getByteLength($c.util.getComponent('ipt_putExerCycle').getValue()) == 0) {
                await $c.win.alert("'풋옵션 행사주기'를 입력하십시오.");
                $c.util.getComponent("ipt_putExerCycle").focus();
                return false;
            }
            if ($c.str.getByteLength($c.util.getComponent('ipt_putExerCnt').getValue()) == 0) {
                await $c.win.alert("'풋옵션 행사횟수'를 입력하십시오.");
                $c.util.getComponent("ipt_putExerCnt").focus();
                return false;
            }
        }
    }
    return true;
    /* sdd-asis-lifecycle:end */
};


// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)
/**
 * @method
 * @name scwin.autoCalcDone
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
 * @hidden N
*/
scwin.autoCalcDone = function (data) {
    /* sdd-asis-lifecycle:begin fn_autoCalc_done — as-is 원문 본문(전환 이관 · 포팅 적용됨) */scwin.result = (typeof data === "string" ? JSON.parse(data) : data);
    $(scwin.result.arrList).each(function(i, item) {
            if (id === "Call") {
                if (i == 0) {
                    $c.util.getComponent('cal_callExerStrtDd1').setValue(item.day);
                    $("input[name='call_exer_end_dd_1']").val(item.day);
                } else {
                    scwin.addRow('Call');
                    $("input[name='call_exer_strt_dd_" + (i + 1) + "']").val(item.day);
                    $("input[name='call_exer_end_dd_" + (i + 1) + "']").val(item.day);
                }
            } else {
                if (id === "Put") {
                    if (i == 0) {
                        $c.util.getComponent('cal_putExerStrtDd1').setValue(item.day);
                        $("input[name='put_exer_end_dd_1']").val(item.day);
                    } else {
                        scwin.addRow('Put');
                        $("input[name='put_exer_strt_dd_" + (i + 1) + "']").val(item.day);
                        $("input[name='put_exer_end_dd_" + (i + 1) + "']").val(item.day);
                    }
                }
            }
    });
    /* sdd-asis-lifecycle:end */
};

/**
 * @method
 * @name scwin.autoCalc
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.autoCalc = async function () {
    const r = await scwin.tx_fn_autoCalc();
    try {
        scwin.autoCalcDone.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body != null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldbnf05004.fn_autoCalc' });
    }
    return r;
};
